        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    regulatoryExposure: 75,
                    stakeholderTrust: 45,
                    businessPerformance: 70,
                    governanceMaturity: 1.0,
                    regulatoryHistory: [],
                    trustHistory: [],
                    businessHistory: [],
                    maturityHistory: [],
                    decisionScoreHistory: [],
                    totalScore: 0
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    choice: 0
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var sel = document.getElementById('decisionSelect');
            if (sel) decisions.choice = parseInt(sel.value);
            if (isNaN(decisions.choice) || decisions.choice < 0 || decisions.choice > 4) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('decision_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var choice = d.choice;

            var regDelta = round.scores.regulatory[choice];
            var trustDelta = round.scores.trust[choice];
            var bizDelta = round.scores.business[choice];
            var matDelta = round.scores.maturity[choice];

            state.domainState.regulatoryExposure = Math.max(0, Math.min(100, state.domainState.regulatoryExposure + regDelta));
            state.domainState.stakeholderTrust = Math.max(0, Math.min(100, state.domainState.stakeholderTrust + trustDelta));
            state.domainState.businessPerformance = Math.max(0, Math.min(100, state.domainState.businessPerformance + bizDelta));
            state.domainState.governanceMaturity = Math.max(1.0, Math.min(5.0, Math.round((state.domainState.governanceMaturity + matDelta) * 10) / 10));

            var isOptimal = (choice === round.optimalChoice) ? 1 : 0;
            var decisionScore = isOptimal ? 100 : Math.max(20, 100 - Math.abs(choice - round.optimalChoice) * 25);

            state.domainState.regulatoryHistory.push(state.domainState.regulatoryExposure);
            state.domainState.trustHistory.push(state.domainState.stakeholderTrust);
            state.domainState.businessHistory.push(state.domainState.businessPerformance);
            state.domainState.maturityHistory.push(state.domainState.governanceMaturity);
            state.domainState.decisionScoreHistory.push(decisionScore);
            state.domainState.totalScore = Math.round(state.domainState.decisionScoreHistory.reduce(function(s, v) { return s + v; }, 0) / state.domainState.decisionScoreHistory.length);

            // overallScore mirrors totalScore, the same running average of decisionScore
            // (already 0-100) that getPerformanceSummary uses for its avgScore verdict
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, state.domainState.totalScore)) });

            var n = roundIdx + 1;
            var feedbackText = this._tr('round' + n + '_fb' + (choice + 1), round.feedback[choice]);
            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackEl = document.getElementById('feedbackText');
            if (feedbackPanel && feedbackEl) {
                feedbackEl.innerHTML = feedbackText;
                feedbackPanel.style.display = 'block';
            }

            // Advance briefing + decision options to the next round synchronously, before the
            // engine increments currentPeriod, using the correct next value. Keep the feedback
            // panel visible so the player can read the governance feedback for the round just played.
            var nextPeriod = (state.currentPeriod || 1) + 1;
            if (nextPeriod <= (state.maxPeriods || this.ROUNDS.length)) {
                this._renderRound(nextPeriod);
            }

            return {
                period: state.currentPeriod,
                choiceLabel: this._tr('round' + n + '_opt' + (choice + 1), round.options[choice]).substring(0, 60),
                decisionScore: decisionScore,
                regulatoryExposure: state.domainState.regulatoryExposure,
                stakeholderTrust: state.domainState.stakeholderTrust,
                businessPerformance: state.domainState.businessPerformance,
                governanceMaturity: state.domainState.governanceMaturity,
                totalScore: state.domainState.totalScore
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('regulatoryDisplay', 'domainState.regulatoryExposure', function(v) { return Math.round(v); });
            uiManager.bind('trustDisplay', 'domainState.stakeholderTrust', function(v) { return Math.round(v); });
            uiManager.bind('businessDisplay', 'domainState.businessPerformance', function(v) { return Math.round(v); });
            uiManager.bind('maturityDisplay', 'domainState.governanceMaturity', function(v) { return v.toFixed(1); });
        }

