        getChartData(state) {
            var labels = state.domainState.regulatoryHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                metricsChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.regulatoryHistory },
