        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.decisionScore || 0 : 0; });
            var avgScore = Math.round(scores.reduce(function(s, v) { return s + v; }, 0) / scores.length);
            var lastRecord = history[history.length - 1];
            var finalReg = lastRecord.results ? lastRecord.results.regulatoryExposure : 75;
            var finalTrust = lastRecord.results ? lastRecord.results.stakeholderTrust : 45;
            var finalBiz = lastRecord.results ? lastRecord.results.businessPerformance : 70;
            var finalMat = lastRecord.results ? lastRecord.results.governanceMaturity : 1.0;

            var performance = this._tr('perf_developing', 'Developing');
            if (avgScore >= 80 && finalMat >= 3.0 && finalReg < 50) performance = this._tr('perf_leader', 'Governance Leader');
            else if (avgScore >= 60 && finalMat >= 2.5) performance = this._tr('perf_competent', 'Competent');
            else if (avgScore >= 40) performance = this._tr('perf_developing', 'Developing');
            else performance = this._tr('perf_needs_improve', 'Needs Improvement');

            var insights = [];
            if (finalReg > 60) insights.push(this._tr('insight_reg_high', 'Regulatory exposure remains dangerously high. EU AI Act enforcement could be imminent.'));
            if (finalReg <= 40) insights.push(this._tr('insight_reg_low', 'Strong regulatory risk reduction. GIF is well-positioned for EU AI Act compliance.'));
            if (finalTrust >= 65) insights.push(this._tr('insight_trust_high', 'Excellent stakeholder trust. Your governance choices built genuine credibility.'));
            if (finalTrust < 35) insights.push(this._tr('insight_trust_low', 'Stakeholder trust is critically low. Reputational damage may be difficult to reverse.'));
            if (finalMat >= 3.0) insights.push(this._tr('insight_maturity_high', 'Governance maturity reached Level 3 (Defined) \u2014 a significant organizational achievement.'));
            if (finalBiz < 55) insights.push(this._tr('insight_biz_low', 'Business performance suffered significantly. Finding the balance between governance and performance is essential.'));
            if (insights.length === 0) insights.push(this._tr('insight_mixed', 'Mixed results across governance dimensions. The CAIGO role requires balancing competing priorities.'));

            return {
                avgScore: avgScore,
                finalRegulatory: finalReg,
                finalTrust: finalTrust,
                finalBusiness: finalBiz,
                finalMaturity: finalMat,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (state.domainState.regulatoryExposure > 70) return window.mySimulation.t('hint_regulatory_high');
            if (state.domainState.stakeholderTrust < 30) return window.mySimulation.t('hint_trust_low');
            if (state.domainState.governanceMaturity < 1.5 && state.currentPeriod > 2) return window.mySimulation.t('hint_maturity_low');
            return null;
        }

